UPDATE public.healthcare_providers SET address = 'Mehdi Abbasov küç. 2, Bakı 1060', address_en = 'Mehdi Abbasov str. 2, Baku 1060', specialty = 'Mamalıq-ginekologiya, Süni mayalanma (İVF), Neonatologiya (çoxprofilli)', specialty_en = 'Obstetrics-Gynecology, IVF, Neonatology (multidisciplinary)' WHERE name = 'Liv Bona Dea Hospital' AND country_code = 'AZ';

